import React from "react";
import { Link } from "react-router-dom";
import "./Home.css";

const Home = () => {
  return (
    <div className="home">
      <h1>🚑 Emergency Contact App</h1>

      <p className="subtitle">
        Your safety, one click away.
      </p>

      <div className="features">
        <div className="feature-card">📞 Quick Emergency Calls</div>
        <div className="feature-card">👨‍👩‍👧 Store Trusted Contacts</div>
        <div className="feature-card">⚡ Fast & Secure Access</div>
      </div>

      <div className="buttons">
        <Link to="/emergency" className="btn primary">
          Go to Emergency Contacts
        </Link>
      </div>
    </div>
  );
};

export default Home;
